// Generated by tooling/unicode-cases/regexp.ts; Node 24.20.0, Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, The design and Staying identical to node.
// Context: long s must retain the Unicode-aware simple-fold path into ASCII.
const pattern0 = /^s$/i;
const pattern1 = /^s$/iu;
const pattern2 = /^s$/iv;
const samples: [string, boolean, boolean, boolean][] = [
  ["\u0053", true, true, true],
  ["\u0073", true, true, true],
  ["\u017f", false, true, true],
  ["\u00df", false, false, false],
  ["\u0073\u0073", false, false, false],
];
for (const sample of samples) {
  assert.sameValue(pattern0.test(sample[0]), sample[1], "long-s-simple-fold pattern 0");
  assert.sameValue(pattern1.test(sample[0]), sample[2], "long-s-simple-fold pattern 1");
  assert.sameValue(pattern2.test(sample[0]), sample[3], "long-s-simple-fold pattern 2");
}
